const paymentPortal=!!document.querySelector('.portal-body');
const paymentLabel=order=>order.paymentStatus==='Paid'?'Paid · verified by store':order.paymentStatus==='Verification pending'?'Payment submitted · awaiting bank check':order.paymentStatus==='Refund required'?'Refund required · contact the store':order.paymentStatus==='Refunded'?'Refund recorded by store':'Not paid';
window.WCOrderPayment=order=>order.paymentMethod!=='UPI'?'':`<div class="payment-summary"><b>UPI · ${escape(paymentLabel(order))}</b>${order.paymentIssue?`<p>${escape(order.paymentIssue)}</p>`:''}${WCPayment.canPay(order)?`<button class="add" data-upi-order="${escape(order.id)}">${order.paymentStatus==='Verification pending'?'View payment':'Pay with UPI · '+money(order.total)}</button>`:order.status==='Pending confirmation'?'<small>Payment opens after the store accepts.</small>':order.status==='Rejected'?'<small>Do not send payment for this cancelled order. Contact the store if you already paid.</small>':''}</div>`;
window.WCAdminPayment=order=>order.paymentMethod!=='UPI'?'':`<div class="payment-summary"><b>${escape(paymentLabel(order))}</b>${order.paymentReference?`<small>Customer reference: ${escape(order.paymentReference)}</small>`:''}${order.confirmedPaymentReference?`<small>Verified reference: ${escape(order.confirmedPaymentReference)}</small>`:''}${order.refundReference?`<small>Refund reference: ${escape(order.refundReference)}</small>`:''}${!['New','Pending confirmation'].includes(order.status)&&!['Paid','Refund required','Refunded'].includes(order.paymentStatus)?`<button class="portal-button" data-payment-action="confirm" data-payment-order="${escape(order.id)}">Check bank & confirm payment</button>`:''}${order.paymentStatus==='Verification pending'?`<button class="text-button" data-payment-action="not-received" data-payment-order="${escape(order.id)}">Payment not found in bank</button>`:''}${order.paymentStatus==='Refund required'?`<p class="rejection-note">Refund externally through your bank first.</p><button class="portal-button" data-payment-action="refund" data-payment-order="${escape(order.id)}">Record completed refund</button>`:''}</div>`;
function qrPanel(amount,reference,caption){
 const displayAmount='₹'+Number(amount).toLocaleString('en-IN',{minimumFractionDigits:2,maximumFractionDigits:2});
 const uri=WCPayment.uri(amount,reference),qr=qrcode(0,'M');qr.addData(uri);qr.make();
 return `<div class="upi-payment"><span class="payment-eyebrow">DIRECT BANK UPI</span><h2>${caption}</h2><strong class="upi-amount">${displayAmount}</strong><div class="upi-qr">${qr.createSvgTag({cellSize:5,margin:20,scalable:true})}</div><b>${escape(WCPayment.merchant.name)}</b><p>${escape(WCPayment.merchant.upi)}</p><small>${escape(WCPayment.merchant.bank)} · INR</small>${`<a class="primary wide upi-link" href="${escape(uri)}">Open UPI app · ${displayAmount}</a>`}<p class="form-note">Amount is pre-filled. Check the recipient name and amount in your UPI app before authorising. Never enter your UPI PIN in this website.</p><p class="form-note">No gateway fee added by Wakad Circle. Your bank’s terms apply.</p></div>`;
}
function showOrderPayment(id){
 const order=orders.find(o=>o.id===id);if(!order||!WCPayment.canPay(order))return notify('This order is not awaiting a UPI payment.');
 commerceModal('upipay',(order.paymentStatus==='Verification pending'?'<h2>Payment is being checked.</h2>':qrPanel(order.total,order.paymentRef||('WC'+order.id.replace(/[^a-zA-Z0-9]/g,'').slice(-24)),'Your order, ready to pay.'))+`<p class="payment-status">${escape(paymentLabel(order))}</p>${order.paymentStatus==='Verification pending'?'<p class="form-note">The store is checking its bank statement. Do not pay again.</p>':`<form id="upireference"><label>Already paid? Enter the 12-digit UTR / RRN<input name="reference" required pattern="[0-9]{12}" maxlength="12" inputmode="numeric" autocomplete="off"></label><p class="form-note">Submitting a reference does not mark the order paid. The shopkeeper must verify receipt.</p><button class="primary wide">Submit for bank verification</button></form>`}<button class="text-button wide" id="paymentback">Back to my orders</button>`);
 $('#modal').dataset.paymentOrder=id;$('#paymentback').onclick=showCustomerOrders;
 if($('#upireference'))$('#upireference').onsubmit=async event=>{event.preventDefault();const b=event.target.querySelector('button');b.disabled=true;const reference=new FormData(event.target).get('reference');try{await window.WKCloud.submitPaymentReference(id,reference);$('#modal').close();notify('Submitted. Please wait for the store’s bank check.')}catch(e){notify(e.message);b.disabled=false}};
}
function bankReview(id,action){
 const order=orders.find(o=>o.id===id);if(!order||!allowed())return;
 showModal(`<h2>${action==='refund'?'Record a completed refund':action==='not-received'?'Payment not received?':'Verify the bank receipt'}</h2><p class="form-note">${escape(order.name)} · ${money(order.total)}. ${action==='refund'?'This only records a refund you have already sent through your bank.':action==='not-received'?'Check the bank statement and settlement delays before asking the customer to try again.':'Check the actual Axis Bank credit. A customer screenshot or reference alone is not proof of receipt.'}</p><form id="bankreview">${action==='not-received'?'':`<label>${action==='refund'?'Refund':'Received payment'} UTR / RRN<input name="reference" required pattern="[0-9]{12}" maxlength="12" inputmode="numeric" value="${escape(action==='confirm'?order.paymentReference||'':'')}"></label><label>Amount ${action==='refund'?'refunded':'received'} (₹)<input name="amount" type="number" required min="1" max="100000" step=".01" placeholder="Enter the bank receipt amount"></label>`}<label class="consent"><input name="checkedBank" type="checkbox" required> I checked the bank statement and confirmed ${action==='refund'?'the full refund was sent':action==='not-received'?'this payment has not arrived':'the full amount was received'}.</label><button class="primary wide">${action==='refund'?'Record refund':action==='not-received'?'Mark payment unverified':'Mark paid after bank check'}</button></form>`);
 $('#bankreview').onsubmit=async event=>{event.preventDefault();const b=event.target.querySelector('button');b.disabled=true;const data=Object.fromEntries(new FormData(event.target));try{const payload={id,action,reference:data.reference,amount:Number(data.amount),checkedBank:true};await window.WKCloud.managePayment(payload);$('#modal').close();notify('Payment record updated')}catch(e){notify(e.message);b.disabled=false}};
}
function collectAmount(){
 if(!allowed())return notify('Shopkeeper sign-in required.');
 showModal('<h2>Collect with UPI.</h2><p class="form-note">Enter a counter-sale amount to generate a QR with that amount pre-filled. Confirm receipt in your bank app. Counter payments are not linked to online orders.</p><form id="collectamount"><label>Amount to collect (₹)<input name="amount" required type="number" min="1" max="100000" step=".01" inputmode="decimal" placeholder="For example: 249.50"></label><button class="primary wide">Generate amount QR</button></form>');
 $('#collectamount').onsubmit=event=>{event.preventDefault();try{const amount=Number(new FormData(event.target).get('amount'));WCPayment.amount(amount);showModal(qrPanel(amount,'WC'+crypto.randomUUID().replaceAll('-','').slice(0,20),'Scan. Pay. Sorted.')+'<button class="text-button wide" id="newcollection">Enter another amount</button>');$('#newcollection').onclick=collectAmount}catch(e){notify(e.message)}};
}
document.addEventListener('click',event=>{const pay=event.target.closest('[data-upi-order]'),review=event.target.closest('[data-payment-action]');if(pay&&!paymentPortal)showOrderPayment(pay.dataset.upiOrder);if(review&&paymentPortal)bankReview(review.dataset.paymentOrder,review.dataset.paymentAction)});
if(paymentPortal){const button=document.createElement('button');button.className='portal-button';button.id='collectupi';button.textContent='₹ Collect UPI';button.onclick=collectAmount;$('.portal-header-actions').prepend(button);renderPortal()}
else{const receiver=window.WK.receiveOrders;window.WK.receiveOrders=function(list){receiver(list);const id=$('#modal').dataset.paymentOrder,order=list.find(o=>o.id===id);if($('#modal').open&&$('#modal').dataset.view==='upipay'&&order&&['Paid','Refund required','Refunded'].includes(order.paymentStatus))showCustomerOrders()}}
